<script setup lang="ts">
import { onMounted, ref } from 'vue'
import Icon from '../components/Icon.vue'
import Modal from '../components/Modal.vue'
import StateBox from '../components/StateBox.vue'
import { api, date, messageOf, post } from '../lib/api'
import { notify, requireLogin, session } from '../lib/session'
import type { ApiKey } from '../lib/types'
const keys = ref<ApiKey[]>([]), loading = ref(false), error = ref(''), createOpen = ref(false), name = ref(''), busy = ref(false), actionError = ref(''), revealed = ref(''), revoke = ref<ApiKey | null>(null)
async function load() { if (!session.token) return; loading.value = true; error.value = ''; try { keys.value = (await api<ApiKey[]>('/gateway/api-keys')).data || [] } catch (e) { error.value = messageOf(e) } finally { loading.value = false } }
function openCreate() { if (!requireLogin()) return; name.value = ''; revealed.value = ''; actionError.value = ''; createOpen.value = true }
async function create() {
  if (!name.value.trim() || busy.value) return
  busy.value = true; actionError.value = ''
  try { const result = await api<ApiKey>('/gateway/api-keys', post({ name: name.value.trim() })); if (!result.data?.key) throw new Error('服务未返回密钥，请检查密钥列表后再试。'); revealed.value = result.data.key; await load() }
  catch (e) { actionError.value = messageOf(e) } finally { busy.value = false }
}
async function disable() { if (!revoke.value) return; busy.value = true; actionError.value = ''; try { await api(`/gateway/api-keys/${encodeURIComponent(revoke.value.id)}`, { method: 'DELETE' }); revoke.value = null; notify('密钥已禁用。'); await load() } catch (e) { actionError.value = messageOf(e) } finally { busy.value = false } }
async function copy() { try { await navigator.clipboard.writeText(revealed.value); notify('密钥已复制，请妥善保存。') } catch { actionError.value = '无法访问剪贴板，请手动选择并复制密钥。' } }
function closeCreate() { if (busy.value) return; revealed.value = ''; createOpen.value = false }
onMounted(load)
</script>
<template><div class="page-heading"><div><span class="eyebrow">API ACCESS</span><h1>连接你的应用与模型</h1><p>为不同应用创建独立密钥，让访问清晰可控。</p></div><button class="btn btn-primary" @click="openCreate"><Icon name="plus" :size="17" />创建密钥</button></div><div class="notice notice-inline"><Icon name="key" :size="18" /><span>完整密钥仅在创建时显示一次。请在服务端保存密钥，避免写入公开代码或前端页面。</span></div><section class="panel"><div class="panel-heading"><h2>我的 API 密钥</h2><button class="btn btn-secondary btn-sm" :disabled="loading" @click="load"><Icon name="refresh" :size="15" />刷新</button></div><StateBox v-if="!session.token" title="登录后管理你的密钥" description="使用密钥，让应用通过统一接口调用模型。"><button class="btn btn-primary" @click="session.loginOpen = true">登录 / 注册</button></StateBox><StateBox v-else-if="loading || error" :loading="loading" :error="error" @retry="load" /><StateBox v-else-if="!keys.length" title="创建你的第一把密钥" description="密钥用于 API 调用；网页模型体验使用当前登录会话。"><button class="btn btn-primary" @click="openCreate">创建密钥</button></StateBox><div v-else class="table-scroll"><table><thead><tr><th>名称</th><th>密钥前缀</th><th>状态</th><th>创建时间</th><th>最近使用</th><th>操作</th></tr></thead><tbody><tr v-for="key in keys" :key="key.id"><td><strong>{{ key.name }}</strong></td><td class="mono">{{ key.prefix }}••••••••</td><td><span class="tag" :class="{ 'tag-green': key.status == null || key.status === 1 }">{{ key.status === 0 ? '已禁用' : '可用' }}</span></td><td class="nowrap">{{ date(key.createdAt || key.createTime) }}</td><td class="nowrap">{{ date(key.lastUsedAt) }}</td><td><button class="text-button danger" :disabled="key.status === 0" @click="revoke = key; actionError = ''">禁用</button></td></tr></tbody></table></div></section><section class="bottom-banner"><div class="banner-icon"><Icon name="book" :size="28" /></div><div><h3>几行代码，开始调用</h3><p>查看 cURL 和 Python 示例，将模型能力接入你的应用。</p></div><RouterLink to="/guide" class="btn btn-secondary">查看文档 <Icon name="arrow" :size="16" /></RouterLink></section><Modal v-if="createOpen" :title="revealed ? '密钥已创建' : '创建 API 密钥'" :locked="busy" @close="closeCreate"><template v-if="revealed"><div class="notice">请立即复制并保存。关闭窗口后将无法再次查看完整密钥。</div><label class="form-label">你的 API 密钥<textarea :value="revealed" readonly class="mono key-secret" aria-label="新创建的 API 密钥" /></label><button class="btn btn-primary full-width" @click="copy"><Icon name="copy" :size="16" />复制密钥</button><button class="btn btn-secondary full-width margin-top" @click="closeCreate">我已保存，关闭</button></template><form v-else class="form-stack" @submit.prevent="create"><label>密钥名称<input v-model="name" placeholder="例如：知识库开发环境" maxlength="64" required /></label><p class="muted small">名称用于区分应用或环境，不会包含在模型请求中。</p><button class="btn btn-primary full-width" :disabled="busy || !name.trim()">{{ busy ? '正在创建…' : '创建密钥' }}</button></form><p v-if="actionError" class="error-text" role="alert">{{ actionError }}</p></Modal><Modal v-if="revoke" title="禁用 API 密钥" :locked="busy" @close="!busy && (revoke = null)"><p>确认禁用「{{ revoke.name }}」？使用此密钥的应用将无法继续发起新请求。</p><p v-if="actionError" class="error-text" role="alert">{{ actionError }}</p><div class="modal-actions"><button class="btn btn-secondary" :disabled="busy" @click="revoke = null">取消</button><button class="btn btn-danger" :disabled="busy" @click="disable">{{ busy ? '正在禁用…' : '确认禁用' }}</button></div></Modal></template>
